{"code":"import numpy as np
# Identify frames and fill interiors with complementary color pattern
grid = self.grid
h, w = self.height, self.width

# color complement mapping as per training: border->fill
comp = {1:4, 2:8, 3:5, 4:1, 5:3, 8:2}

# Find frames
frames = []  # list of (color, x1, y1, x2, y2)
for c in np.unique(grid):
    if c == 0:
        continue
    # find all positions of color c
    ys, xs = np.where(grid == c)
    if len(xs) == 0:
        continue
    x1, x2 = xs.min(), xs.max()
    y1, y2 = ys.min(), ys.max()
    # bounding box dims
    if x2 - x1 < 2 or y2 - y1 < 2:
        continue
    # check border positions all equal c and interior positions have no c
    ok = True
    # top and bottom edges
    for x in range(x1, x2+1):
        if grid[y1, x] != c or grid[y2, x] != c:
            ok = False
            break
    # left and right edges
    if ok:
        for y in range(y1, y2+1):
            if grid[y, x1] != c or grid[y, x2] != c:
                ok = False
                break
    # interior should not contain c to be a frame
    if ok:
        for y in range(y1+1, y2):
            for x in range(x1+1, x2):
                if grid[y, x] == c:
                    ok = False
                    break
            if not ok:
                break
    if ok:
        frames.append((int(c), x1, y1, x2, y2))

# Create output grid blank
out = np.zeros_like(grid)
# draw frames: copy border
for c, x1, y1, x2, y2 in frames:
    # draw horizontal borders
    out[y1, x1:x2+1] = c
    out[y2, x1:x2+1] = c
    # draw vertical borders
    out[y1:y2+1, x1] = c
    out[y1:y2+1, x2] = c
# fill interiors
for c, x1, y1, x2, y2 in frames:
    if c in comp:
        f = comp[c]
    else:
        continue
    # fill interior checkerboard
    start_parity = ((y1+1) + (x1+1)) % 2
    for y in range(y1+1, y2):
        for x in range(x1+1, x2):
            if (y + x) % 2 == start_parity:
                out[y, x] = f
# assign back to grid
self.grid[:] = out","rationale":"Identify rectangular frames by checking bounding boxes and border consistency, then fill their interiors with checkerboard pattern using complementary colors based on mapping from training tasks. All other elements cleared."}
